#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: terminal UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
WRITTEN_VAR=()    # variable NAMEs set this run
SKIPPED=()        # things we could not do, for example gh missing

# _clear wipes the terminal so only the current step is on screen. No-op when
# output is not a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  Run this wizard in a terminal from the project root. You drive the browser;\n' "$DIM"
  printf '  the wizard tells you what to do and captures values here. Stop any time\n'
  printf '  with Ctrl-C and re-run later; saved values are reused.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is an action the human takes in the browser or another tool.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform including WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "could not open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "could not open a browser; visit it manually: $url"
}

# pause "msg" waits for the human to confirm they have done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_unquote_env_value() {
  local value="$1"
  if [[ "$value" == '""' ]]; then
    printf ''
  elif [[ "$value" =~ ^\"(.*)\"$ ]]; then
    value="${value:1:${#value}-2}"
    value=${value//\\\"/\"}
    value=${value//\\\$/\$}
    value=${value//\\\`/\`}
    value=${value//\\\\/\\}
    printf '%s' "$value"
  else
    printf '%s' "$value"
  fi
}

_quote_env_value() {
  local value="$1" escaped
  escaped=${value//\\/\\\\}
  escaped=${escaped//\"/\\\"}
  escaped=${escaped//\$/\\\$}
  escaped=${escaped//\`/\\\`}
  printf '"%s"' "$escaped"
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  _unquote_env_value "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs. Visible input only; use ask_secret for secrets.
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY="VALUE" into ENV_FILE. Values are quoted
# and escaped so spaces and shell metacharacters are safe in typical dotenv files.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$(_quote_env_value "$value")" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. It never
# prints VALUE. It records follow-up work if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable. Use only for non-secrets.
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      WRITTEN_VAR+=("$name")
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name: gh not ready; set it later"
}

# finish clears, then shows a truthful closing summary.
finish() {
  _clear
  if (( ${#SKIPPED[@]} )); then
    printf '\n%s%s  Wizard finished with follow-up steps%s\n' "$BOLD" "$YELLOW" "$RESET"
  else
    printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_VAR[@]} ))    && note "set ${#WRITTEN_VAR[@]} GitHub variable(s): ${WRITTEN_VAR[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: publish and connect the RunWield documentation site.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=3
REPOSITORY="gandazgul/runwield"

banner "RunWield documentation site setup"

stage "Release-aligned documentation branch"
say "Documentation deploys from docs/stable after Stable publication. This wizard does not change product tags."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "GitHub CLI is not authenticated. Run: gh auth login"
  SKIPPED+=("Deploy the latest Stable manual from docs/stable")
elif ! gh api "repos/$REPOSITORY/git/ref/heads/docs/stable" >/dev/null 2>&1; then
  warn "Cannot verify docs/stable. Check access and the branch before deployment."
  note "If the branch does not exist, follow the disposable-checkout bootstrap steps in docs/releasing.md."
  SKIPPED+=("Prepare docs/stable and dispatch docs.yml from that branch")
else
  confirm "Deploy the latest Stable manual from docs/stable?" && \
    gh workflow run docs.yml --repo "$REPOSITORY" --ref docs/stable
  step "Open the workflow run and wait for its deploy job to pass."
  open_url "https://github.com/$REPOSITORY/actions/workflows/docs.yml"
  pause "Continue after the deployment passes."
fi

stage "Move docs.runwield.dev to GitHub Pages"
say "The hostname currently reaches another Cloudflare route. Remove that route before adding the Pages DNS record."
open_url "https://dash.cloudflare.com"
step "Open runwield.dev, then Workers & Pages. Remove docs.runwield.dev from any existing Worker or Pages custom domain."
step "Open DNS > Records. Replace the docs record with CNAME docs → gandazgul.github.io. Use DNS only until GitHub issues its certificate."
pause "Continue after Cloudflare shows the new DNS record."

stage "Verify the custom domain"
open_url "https://github.com/$REPOSITORY/settings/pages"
step "Confirm the source is GitHub Actions and the custom domain is docs.runwield.dev."
step "Wait for the DNS check and TLS certificate, then enable Enforce HTTPS."
step "Open https://docs.runwield.dev and confirm the page identifies the latest Stable release."
open_url "https://docs.runwield.dev"
pause "Press Enter after the site and a deep guide link load over HTTPS."

finish
